window.RP_SESSION={"id":"S-1740bcc3a159","messages":[{"id":"RP-III-0155703","time":"2026-08-23T00:48:00+09:00","room":"RP III","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":" 뒹굴-\n\n대장간 안쪽 마당.\n와인 캐스크를 발로 밀어서 굴렸다.\n\n최근에 바다에 갔었지.\n갑옷은 어디 벗어뒀지만 바닷물을 맞고 녹이 좀 슬었어.\n\n덕분에 사슬갑옷과 모래, 식초를 나무통에 넣고 이렇게 굴리고 있다.","characters":["P-55e987e3c831"]},{"id":"RP-III-0155704","time":"2026-08-23T00:50:00+09:00","room":"RP III","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":" 뒹굴 뒹굴\n\n이걸 아예 거치대에 놓고, 손잡이를 달면 더 좋을 거 같은데.\n아니면 수레처럼 차축과 손잡이를 달고 밀고 다닌다거나.","characters":["P-55e987e3c831"]},{"id":"RP-III-0155705","time":"2026-08-23T01:19:00+09:00","room":"RP III","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"한동안 그렇게 밀어대고 사슬갑옷을 꺼내 촤악! 펼쳤다.\n\n식초물이 뚝뚝 떨어지는 사슬갑옷.\n물로 함 헹궈주고 살펴봤다.\n\n심각한 부분이 좀 보이는걸.\n일단 대장간 안으로 다시 들어갔다.","characters":["P-55e987e3c831"]},{"id":"RP-III-0155706","time":"2026-08-23T01:24:00+09:00","room":"RP III","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"일단 린넨천으로 물기를 꾹꾹 눌러 닦아 없애고...\n\n사슬갑옷 중 검붉은 녹이 되다시피 한 고리들은 커팅 플라이어로 한번 잡아주기만 해도 뚝뚝 끊겨 떨어져나갔다.","characters":["P-55e987e3c831"]},{"id":"RP-III-0155707","time":"2026-08-23T01:25:00+09:00","room":"RP III","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"염분을 머금고 있던 탓인지 연쇄적으로 심하게 녹슬은 부분들을 그렇게 떼어내고.\n\n전에 만들어둔 (사실상 첫 대장간 RP에 나온) 사슬천을 덧대다가 붙이지.","characters":["P-55e987e3c831"]},{"id":"RP-III-0155708","time":"2026-08-23T01:27:00+09:00","room":"RP III","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"급하지 않으니 리벳을 풀어 알맞은 크기와 모양으로 재단하고,\n사슬갑옷의 새로 비어버린 부분에 덧댄다.","characters":["P-55e987e3c831"]},{"id":"RP-III-0155709","time":"2026-08-23T01:28:00+09:00","room":"RP III","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"4-in-1 패턴의 링으로 끼워서, 작은 쐐기형 연철 리벳을 끼운 다음. 전용 집게로 꾸욱 눌러 고리를 닫아준다.","characters":["P-55e987e3c831"]},{"id":"RP-III-0155710","time":"2026-08-23T01:30:00+09:00","room":"RP III","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":" 촤륵!\n\n그렇게 사슬갑옷을 복구하고, 촥 펼쳐 살펴봤다.","characters":["P-55e987e3c831"]},{"id":"RP-III-0155711","time":"2026-08-23T01:30:00+09:00","room":"RP III","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-55e987e3c831"]},{"id":"RP-III-0155712","time":"2026-08-23T01:30:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 11 = 11\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-III-0155713","time":"2026-08-23T01:31:00+09:00","room":"RP III","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"빼먹은 부분은 없는 모양이다.\n\n그럼 녹슬지 말라고 리넨천에 아마씨유를 묻혀다가 사슬갑옷에 덕지덕지 발라준다.\n\n이대로 기름먹인 이 리넨천으로 감싸둬야지.","characters":["P-55e987e3c831"]},{"id":"RP-III-0155714","time":"2026-08-23T01:31:00+09:00","room":"RP III","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-55e987e3c831"]},{"id":"RP-III-0155715","time":"2026-08-23T01:31:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
